import {validate,dateKey,weekDays,summary,schedule,enrichExisting,addTravelPack} from './model.js?v=20261029';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const KEY='mandarin-garden-v1';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=()=>crypto.randomUUID?crypto.randomUUID():'id'+Date.now()+Math.random().toString(16).slice(2);let data,seed,reviewQueue=[],revealed=false,quiz=null,toastTimer,activeView='dashboard';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));$('#storageWarning').hidden=true}catch{$('#storageWarning').hidden=false}render()}
function open(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}function close(){if(quiz&&!quiz.finished&&!quiz.saved){const elapsed=Math.floor((Date.now()-quiz.started)/60000);if(elapsed>0){recordMinutes(Math.min(elapsed,120));persist()}}quiz=null;$('#modal').close()}
$('#closeModal').onclick=close;$('#modal').addEventListener('cancel',e=>{e.preventDefault();close()});function confirmAction(title,desc,fn){open(`<h2>${esc(title)}</h2><p>${esc(desc)}</p><div class="form-actions"><button class="outline" id="cancelAction">취소</button><button class="primary" id="confirmAction">확인</button></div>`);$('#cancelAction').onclick=close;$('#confirmAction').onclick=()=>{fn();close()}}
function speak(text){if(!('speechSynthesis'in window)){toast('이 브라우저는 음성 재생을 지원하지 않습니다.');return}const voices=speechSynthesis.getVoices().filter(v=>/^(zh[-_]CN|cmn([-_]CN)?)$/i.test(v.lang));if(!voices.length){toast('표준중국어(zh-CN) 합성 음성이 없습니다. 기기에 중국어 음성을 설치하거나 다른 브라우저를 사용하세요.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.voice=voices.find(v=>/zh[-_]CN/i.test(v.lang))||voices[0];u.rate=.8;u.onerror=()=>toast('음성 재생에 실패했습니다. 기기 음성 설정을 확인하세요.');speechSynthesis.speak(u)}if('speechSynthesis'in window)speechSynthesis.getVoices();

function pronunciation(w,details=true){return `<div class="pronunciation"><span>한국어 근사치: ${esc(w.koreanPronunciation||'미등록 · 수정에서 입력 가능')}</span><span>성조: ${esc(w.toneNotes||'병음의 성조부호를 확인하세요.')}</span>${details?`<p>${esc(w.wordBreakdown||'단어별 뜻 미등록')}</p>${w.example?`<button class="outline" data-example-speak="${esc(w.id)}">♫ 예문 듣기</button>`:''}`:''}</div>`}
function recommendation(){return data.lessons.find(l=>l.progress<100)||data.lessons[0]}
function renderDashboard(){const s=summary(data),learn=data.vocabulary.length;$('#learnerName').textContent=data.settings.name;$('#stats').innerHTML=[['오늘의 학습',s.todayMinutes,'분',`목표 ${data.settings.dailyGoal}분 · ${Math.min(100,Math.round(s.todayMinutes/data.settings.dailyGoal*100))}% 달성`,'◷'],['연속 학습',s.streak,'일','최근 학습 기록 기준','✳'],['학습한 단어',s.learned,'개',`전체 ${learn}개 중 기억 단계 1 이상`,'字'],['복습할 단어',s.due,'개','오늘까지 복습 예정인 단어','↻']].map(([label,n,unit,note,icon])=>`<article class="stat"><div><div class="stat-label">${label}</div><div class="stat-value">${n}<small>${unit}</small></div><div class="stat-note">${note}</div></div><span class="stat-symbol">${icon}</span></article>`).join('');let l=recommendation();$('#heroKicker').textContent=l?`${l.level} · ${l.topic} · ${l.minutes}분`:'나의 첫 수업';$('#heroTitle').textContent=l?.title||'작은 배움을 시작해요';$('#heroDesc').textContent=l?.description||'수업을 추가하고 나만의 중국어 코스를 만들어 보세요.';$('#heroProgress').textContent=`학습 진행률 ${l?.progress||0}%`;$('#heroBar').style.width=(l?.progress||0)+'%';$('#weeklyTotal').textContent=s.weekly;$('#weekRange').textContent=s.dates[0].slice(5).replace('-','.')+' – '+s.dates[6].slice(5).replace('-','.');const max=Math.max(30,...s.dates.map(d=>data.activity[d]||0));$('#chart').innerHTML=s.dates.map((d,i)=>{const m=data.activity[d]||0;return `<div class="bar-group ${d===dateKey()?'today':''}"><small>${m||''}</small><div class="bar" style="height:${m/max*105}px" role="img" aria-label="${d}, ${m}분"></div><span>${['월','화','수','목','금','토','일'][i]}</span></div>`}).join('');$('#courseCount').textContent=String(data.lessons.length).padStart(2,'0');$('#dashboardLessons').innerHTML=data.lessons.slice(0,3).map(l=>`<div class="course-row"><span class="course-badge">${esc(l.symbol)}</span><div class="course-info"><h3>${esc(l.title)}</h3><p>${esc(l.level)} · ${l.wordIds.length}개 단어 · ${l.minutes}분</p></div><div class="course-progress"><div><i style="width:${l.progress}%"></i></div><span>${l.progress}%</span></div><button data-lesson="${esc(l.id)}" aria-label="${esc(l.title)} 학습 시작">›</button></div>`).join('')||'<p class="empty">아직 수업이 없어요. 나의 수업에서 추가해 주세요.</p>';const word=data.vocabulary.find(v=>v.hanzi==='学习')||data.vocabulary[0];$('#dailyWord').innerHTML=word?`<div class="word-hanzi" lang="zh-CN">${esc(word.hanzi)}</div><div class="word-pinyin">${esc(word.pinyin)}</div>${pronunciation(word)}<p class="word-meaning">${esc(word.meaning)}</p><div class="word-example"><span lang="zh-CN">${esc(word.example)}</span><small>${esc(word.translation)}</small></div>`:'<p class="empty">단어장에 단어를 추가해 주세요.</p>';$('#wordSound').disabled=!word;$('#wordSound').onclick=()=>word&&speak(word.hanzi);$('#wordReview').disabled=!word;$('#wordReview').onclick=()=>{reviewQueue=word?[word.id]:[];revealed=false;location.hash='review';renderReview()};$('#reviewBadge').textContent=s.due}
function renderLessons(){const level=$('#lessonLevel').value;$('#lessonGrid').innerHTML=data.lessons.filter(l=>!level||l.level===level).map(l=>`<article class="lesson-card"><div class="lesson-top"><span class="course-badge">${esc(l.symbol)}</span><span class="level-tag">${esc(l.level)} · ${esc(l.topic)}</span></div><h2>${esc(l.title)}</h2><p>${esc(l.description)}</p><div class="lesson-meta"><span>${l.wordIds.length}개 단어 · ${l.minutes}분</span><span>${l.progress}% 완료</span></div><div class="lesson-track"><i style="width:${l.progress}%"></i></div><div class="lesson-actions"><div><button data-edit-lesson="${esc(l.id)}">수정</button><button class="danger" data-delete-lesson="${esc(l.id)}">삭제</button></div><button class="primary" data-lesson="${esc(l.id)}">학습 시작 →</button></div></article>`).join('')||'<div class="panel empty">해당 레벨의 수업이 없어요. 새 수업을 추가해 보세요.</div>'}
function renderWords(){const selected=$('#wordCategory').value,categories=[...new Set(data.vocabulary.map(w=>w.category))];$('#wordCategory').innerHTML='<option value="">전체</option>'+categories.map(c=>`<option ${c===selected?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('');const query=$('#wordSearch').value.trim().toLowerCase();const cat=$('#wordCategory').value;const words=data.vocabulary.filter(w=>(!cat||w.category===cat)&&(!query||[w.hanzi,w.pinyin,w.meaning,w.koreanPronunciation,w.wordBreakdown].some(x=>x.toLowerCase().includes(query))));$('#wordCount').textContent=`${words.length} / ${data.vocabulary.length}개`;$('#wordRows').innerHTML=words.map(w=>`<tr><td><strong lang="zh-CN">${esc(w.hanzi)}</strong><small>${esc(w.pinyin)}</small>${pronunciation(w)}</td><td>${esc(w.meaning)}</td><td><span class="level-tag">${esc(w.category)}</span></td><td>${esc(w.due)}${w.due<=dateKey()?'<small>복습할 시간이에요</small>':''}</td><td><span class="stage">${w.stage===0?'새 단어':`단계 ${w.stage} / 5`}</span></td><td><button class="icon-btn" data-speak="${esc(w.id)}" aria-label="${esc(w.hanzi)} 발음 듣기">♫</button><button class="icon-btn" data-edit-word="${esc(w.id)}" aria-label="${esc(w.hanzi)} 수정">✎</button><button class="icon-btn danger" data-delete-word="${esc(w.id)}" aria-label="${esc(w.hanzi)} 삭제">×</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">일치하는 단어가 없습니다.</td></tr>'}
function renderReview(){reviewQueue=reviewQueue.filter(id=>data.vocabulary.some(w=>w.id===id));const w=data.vocabulary.find(w=>w.id===reviewQueue[0]);if(!w){$('#reviewCard').innerHTML='<div class="review-count">TODAY’S REVIEW</div><div class="word-hanzi">✳</div><h2>오늘의 복습을 마쳤어요!</h2><p class="muted">전체 단어 연습으로 더 연습하거나 단어장에 새 단어를 추가해 보세요.</p><button class="outline" id="restartReview">전체 단어 연습 →</button>';$('#restartReview').onclick=startAllReview;return}$('#reviewCard').innerHTML=`<div class="review-count">${reviewQueue.length}개 남음 · ${esc(w.category)}</div><div class="word-hanzi" lang="zh-CN">${esc(w.hanzi)}</div><div class="word-pinyin">${esc(w.pinyin)}</div>${pronunciation(w)}<button class="icon-btn" id="reviewSound" aria-label="단어 발음 듣기">♫</button>${revealed?`<div class="word-meaning">${esc(w.meaning)}</div><div class="word-example">${esc(w.example)}<small>${esc(w.translation)}</small></div><div class="review-controls"><button data-rating="again">다시 · 오늘</button><button data-rating="good">보통 · 내일</button><button data-rating="easy">기억해요 ✓</button></div>`:'<p class="muted" style="margin-top:22px">뜻을 떠올려 보세요.</p><button class="outline" id="reveal">뜻 확인하기 →</button>'}`;$('#reviewSound').onclick=()=>speak(w.hanzi);if($('#reveal'))$('#reveal').onclick=()=>{revealed=true;renderReview()}}
function startAllReview(){reviewQueue=data.vocabulary.map(w=>w.id);revealed=false;renderReview()}$('#reviewAll').onclick=startAllReview;
function route(){const v=location.hash.slice(1)||'dashboard';activeView=['dashboard','lessons','vocabulary','review','writing','research'].includes(v)?v:'dashboard';$$('.view').forEach(x=>x.hidden=x.id!=='view-'+activeView);$$('[data-view]').forEach(x=>{const active=x.dataset.view===activeView;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});$('#pageName').textContent={dashboard:'대시보드',lessons:'나의 수업',vocabulary:'단어장',review:'오늘의 복습',writing:'한자 쓰기',research:'서비스 리서치'}[activeView];if(activeView==='review'&&!reviewQueue.length){reviewQueue=data.vocabulary.filter(w=>w.due<=dateKey()).map(w=>w.id);revealed=false}render();window.scrollTo({top:0,behavior:'instant'})}
function render(){renderDashboard();renderLessons();renderWords();renderWriting();if(activeView==='review')renderReview()}
function wordEditor(wordId){const w=data.vocabulary.find(w=>w.id===wordId)||{hanzi:'',pinyin:'',meaning:'',category:'일상',example:'',translation:'',stage:0,due:dateKey()};const fields=[['hanzi','한자',w.hanzi,'text',30],['pinyin','병음',w.pinyin,'text',100],['meaning','한국어 뜻',w.meaning,'text',150],['category','분류',w.category,'text',30],['due','복습 예정일',w.due,'date'],['stage','기억 단계 (0~5)',w.stage,'number']];open(`<h2>${wordId?'단어 수정':'새로운 단어 추가'}</h2><p>단어와 예문은 자유롭게 입력할 수 있어요.</p><form id="editForm"><div class="form-grid">${fields.map(([name,label,value,type,max])=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${max?`maxlength="${max}"`:''} ${type==='number'?'min="0" max="5" step="1"':''}></label>`).join('')}${[['koreanPronunciation','한국어 발음 근사치',200],['toneNotes','성조·변조 설명',500],['wordBreakdown','단어별 뜻 (예: 我=나 | 去=가다)',1000]].map(([key,label,max])=>`<label class="full">${label}<textarea name="${key}" maxlength="${max}">${esc(w[key]||'')}</textarea></label>`).join('')}<label class="full">중국어 예문<textarea name="example" maxlength="300">${esc(w.example)}</textarea></label><label class="full">예문 해석<textarea name="translation" maxlength="300">${esc(w.translation)}</textarea></label></div><div class="field-error" role="alert"></div><div class="form-actions"><button type="button" class="outline" data-close>취소</button><button type="submit" class="primary">저장하기</button></div></form>`);$('#editForm').onsubmit=e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));f.id=wordId||id();f.stage=Number(f.stage);const next=structuredClone(data);if(wordId)next.vocabulary=next.vocabulary.map(x=>x.id===wordId?f:x);else next.vocabulary.push(f);data=validate(next);persist();close();toast('단어를 저장했습니다.')}catch(err){$('.field-error').textContent=err.message}}}
function lessonEditor(lessonId){const l=data.lessons.find(l=>l.id===lessonId)||{title:'',description:'',level:'입문',topic:'일상',minutes:10,progress:0,symbol:'学',wordIds:[]};open(`<h2>${lessonId?'수업 수정':'나만의 수업 만들기'}</h2><form id="editForm"><div class="form-grid"><label class="full">수업명<input name="title" value="${esc(l.title)}" required maxlength="60"></label><label>레벨<select name="level">${['입문','초급','중급'].map(x=>`<option ${l.level===x?'selected':''}>${x}</option>`).join('')}</select></label><label>주제<input name="topic" required maxlength="30" value="${esc(l.topic)}"></label><label>학습 시간 (1~120분)<input name="minutes" type="number" min="1" max="120" required value="${l.minutes}"></label><label>진도 (0~100%)<input name="progress" type="number" min="0" max="100" required value="${l.progress}"></label><label>표시 한자<input name="symbol" required maxlength="2" value="${esc(l.symbol)}"></label><label class="full">수업 설명<textarea name="description" required maxlength="250">${esc(l.description)}</textarea></label><div class="full"><p class="muted">연결할 단어 (${data.vocabulary.length}개 중 선택)</p><div class="checklist">${data.vocabulary.map(w=>`<label><input type="checkbox" name="wordIds" value="${esc(w.id)}" ${l.wordIds.includes(w.id)?'checked':''}>${esc(w.hanzi)} · ${esc(w.meaning)}</label>`).join('')||'먼저 단어장에 단어를 추가해 주세요.'}</div></div></div><div class="field-error" role="alert"></div><div class="form-actions"><button type="button" class="outline" data-close>취소</button><button class="primary">저장하기</button></div></form>`);$('#editForm').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target),f=Object.fromEntries(form);f.minutes=Number(f.minutes);f.progress=Number(f.progress);f.wordIds=form.getAll('wordIds');f.id=lessonId||id();const next=structuredClone(data);if(lessonId)next.lessons=next.lessons.map(x=>x.id===lessonId?f:x);else next.lessons.push(f);data=validate(next);persist();close();toast('수업을 저장했습니다.')}catch(err){$('.field-error').textContent=err.message}}}
function settings(){open(`<h2>나만의 학습 목표</h2><p>목표는 오늘의 학습 카드에 바로 반영됩니다.</p><form id="settingsForm"><div class="form-grid"><label>학습자 이름<input name="name" required maxlength="30" value="${esc(data.settings.name)}"></label><label>하루 목표 (1~180분)<input type="number" name="dailyGoal" min="1" max="180" value="${data.settings.dailyGoal}" required></label></div><div class="form-actions"><button class="primary">목표 저장</button></div></form>`);$('#settingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);data.settings={name:f.get('name').trim()||'학습자',dailyGoal:Number(f.get('dailyGoal'))};persist();close();toast('학습 목표를 저장했습니다.')}}
function activityEditor(){const dates=weekDays();open(`<h2>이번 주 학습 기록</h2><p>실제로 학습한 시간을 직접 기록하세요. 입력값으로 덮어씁니다.</p><form id="activityForm"><div class="form-grid">${dates.map((d,i)=>`<label>${d} (${['월','화','수','목','금','토','일'][i]})<input type="number" name="${d}" min="0" max="1440" step="1" value="${data.activity[d]||0}" required></label>`).join('')}</div><div class="form-actions"><button class="primary">기록 저장</button></div></form>`);$('#activityForm').onsubmit=e=>{e.preventDefault();for(const [d,v] of new FormData(e.target))data.activity[d]=Number(v);persist();close();toast('주간 기록을 저장했습니다.')}}
function exportJSON(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mandarin-garden-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('JSON 백업 파일을 내보냈습니다.')}
function dataDialog(){open('<h2>나의 학습 데이터</h2><p>서버나 데이터베이스 없이 이 브라우저에만 저장합니다. 다른 기기로 옮기기 전 JSON을 내보내 주세요.</p><button class="outline" id="addTravelPack">상하이 여행 자료 15개 추가 · 기존 기록 유지</button><div class="data-actions"><button id="exportData">↓ JSON 내보내기<small>단어·수업·복습·목표·기록 전체 백업</small></button><button id="chooseImport">↑ JSON 가져오기<small>검사 후 미리보기 · 확인하면 전체 교체</small></button></div><input id="jsonFile" type="file" accept=".json,application/json" hidden><div id="importPreview"></div><div class="file-note">브라우저 데이터 삭제·다른 기기·다른 주소에서는 데이터가 이어지지 않습니다. 가져오기 전에 현재 데이터를 백업하세요.<br>원본 data.json은 바뀌지 않으며, 수정 내용은 브라우저 저장과 내보낸 JSON에 반영됩니다.</div><div class="form-actions"><button class="danger subtle" id="resetData">초기 가상 데이터로 복원</button></div>');$('#addTravelPack').onclick=()=>{try{data=addTravelPack(data,seed);persist();close();toast('상하이 여행 자료를 추가했습니다. 기존 항목은 유지됩니다.')}catch(err){toast(err.message)}};$('#exportData').onclick=exportJSON;$('#chooseImport').onclick=()=>$('#jsonFile').click();$('#jsonFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('5MB 이하의 JSON 파일만 가져올 수 있습니다.');return}try{const candidate=enrichExisting(validate(JSON.parse(await file.text())),seed);$('#importPreview').innerHTML=`<div class="file-note">가져올 데이터: 단어 ${candidate.vocabulary.length}개 · 수업 ${candidate.lessons.length}개 · 학습자 ${esc(candidate.settings.name)}<br>현재 데이터를 모두 교체합니다.</div><div class="form-actions"><button class="outline" id="cancelImport">취소</button><button class="primary" id="applyImport">데이터 교체</button></div>`;$('#cancelImport').onclick=()=>$('#importPreview').replaceChildren();$('#applyImport').onclick=()=>{data=candidate;reviewQueue=data.vocabulary.filter(w=>w.due<=dateKey()).map(w=>w.id);revealed=false;persist();close();toast('검사된 JSON 데이터를 적용했습니다.')}}catch(err){$('#importPreview').textContent='가져오기 실패: '+err.message}};$('#resetData').onclick=()=>confirmAction('초기 가상 데이터로 복원할까요?','현재 단어·수업·복습·기록을 초기 예시로 교체합니다. 필요한 데이터는 먼저 내보내 주세요.',()=>{data=structuredClone(seed);reviewQueue=data.vocabulary.filter(w=>w.due<=dateKey()).map(w=>w.id);revealed=false;persist();toast('초기 가상 데이터를 복원했습니다.')})}
function recordMinutes(minutes){const today=dateKey();data.activity[today]=Math.min(1440,(data.activity[today]||0)+minutes)}
function startLesson(lessonId){const lesson=data.lessons.find(l=>l.id===lessonId);if(!lesson)return;const words=lesson.wordIds.map(id=>data.vocabulary.find(w=>w.id===id)).filter(Boolean);if(!words.length){toast('학습할 단어가 없습니다. 수업 수정에서 단어를 선택해 주세요.');return}quiz={lessonId,words,index:0,correct:0,answered:false,started:Date.now(),saved:false};quizQuestion()}
function shuffled(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function quizQuestion(){const q=quiz,w=q.words[q.index];q.answered=false;const alternatives=[...new Set(data.vocabulary.map(v=>v.meaning))].filter(x=>x!==w.meaning);q.options=shuffled([w.meaning,...shuffled(alternatives).slice(0,3)]);open(`<h2>${esc(data.lessons.find(l=>l.id===q.lessonId)?.title||'단어 학습')}</h2><div class="quiz-footer"><span>단어 뜻 고르기</span><span>${q.index+1} / ${q.words.length}</span></div><div class="quiz-prompt" lang="zh-CN">${esc(w.hanzi)}</div><div class="quiz-pinyin">${esc(w.pinyin)} <button id="quizSound" aria-label="발음 듣기">♫</button></div>${pronunciation(w,false)}<div class="quiz-options">${q.options.map((o,i)=>`<button data-option="${i}">${esc(o)}</button>`).join('')}</div><p id="quizFeedback" role="status"></p><div class="form-actions"><button class="primary" id="quizNext" disabled>${q.index+1===q.words.length?'결과 보기':'다음 단어 →'}</button></div>`);$('#quizSound').onclick=()=>speak(w.hanzi);$$('[data-option]').forEach(b=>b.onclick=()=>{if(q.answered)return;q.answered=true;const right=q.options[Number(b.dataset.option)]===w.meaning;if(right)q.correct++;$$('[data-option]').forEach(x=>{x.disabled=true;if(q.options[Number(x.dataset.option)]===w.meaning)x.classList.add('correct')});if(!right)b.classList.add('wrong');$('#quizFeedback').textContent=right?'정답이에요! '+w.example:'정답은 “'+w.meaning+'”입니다. '+w.translation;$('#quizFeedback').insertAdjacentHTML('beforeend',pronunciation(w));$('#quizNext').disabled=false});$('#quizNext').onclick=()=>{if(!q.answered)return;q.index++;if(q.index<q.words.length)quizQuestion();else finishQuiz()}}
function finishQuiz(){const q=quiz;if(q.saved)return;q.saved=true;q.finished=true;const total=q.words.length;const percent=Math.round(q.correct/total*100);const lesson=data.lessons.find(l=>l.id===q.lessonId);if(lesson)lesson.progress=Math.max(lesson.progress,percent);data.results.push({date:dateKey(),lessonId:q.lessonId,correct:q.correct,total});if(data.results.length>10000)data.results.shift();recordMinutes(Math.max(1,Math.min(120,Math.ceil((Date.now()-q.started)/60000))));persist();open(`<div class="quiz-result"><span class="eyebrow">ANOTHER SMALL STEP FORWARD</span><h2>오늘도 한 걸음 더!</h2><strong>${q.correct} / ${total}</strong><p>이번 학습 정답률 ${percent}% · 코스 진도는 최고 정답률로 표시됩니다.</p><p>학습한 내용을 복습 카드로 한 번 더 익혀 보세요.</p><button class="primary" id="finishClose">학습 마치기 ✓</button></div>`);$('#finishClose').onclick=()=>{close();toast('학습 결과와 시간을 저장했습니다.')}}
function renderWriting(){const select=$('#writingWord'),selected=select.value;select.innerHTML=data.vocabulary.map(w=>`<option value="${esc(w.id)}" ${w.id===selected?'selected':''}>${esc(w.hanzi)} · ${esc(w.meaning)}</option>`).join('');const w=data.vocabulary.find(w=>w.id===select.value);$('#writingGhost').textContent=w?.hanzi||'字';$('#writingInfo').innerHTML=w?`<span class="eyebrow">WRITE & REMEMBER</span><h2 lang="zh-CN">${esc(w.hanzi)}</h2><div class="word-pinyin">${esc(w.pinyin)}</div>${pronunciation(w)}<p style="margin-top:20px">${esc(w.meaning)}</p><div class="word-example"><span lang="zh-CN">${esc(w.example)}</span><small>${esc(w.translation)}</small></div><p>옅은 글씨를 따라 마우스나 손가락으로 써 보세요. 여러 글자는 한 번에 표시됩니다.</p><p>이 연습장은 필순이나 발음을 채점하지 않으며, 그린 내용은 저장하지 않습니다.</p>`:'<p>단어장에 단어를 먼저 추가해 주세요.</p>';$('#writingSound').disabled=!w}
const canvas=$('#writingCanvas'),ctx=canvas.getContext('2d');let drawing=false;ctx.lineWidth=8;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#3b6849';function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*640/r.width,(e.clientY-r.top)*640/r.height]}canvas.onpointerdown=e=>{if(e.button!==0&&e.pointerType==='mouse')return;drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e))};canvas.onpointermove=e=>{if(drawing){ctx.lineTo(...point(e));ctx.stroke()}};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;$('#clearWriting').onclick=()=>ctx.clearRect(0,0,640,640);$('#writingWord').onchange=()=>{$('#clearWriting').click();renderWriting()};$('#showGuide').onchange=e=>$('#writingGhost').hidden=!e.target.checked;$('#writingSound').onclick=()=>{const w=data.vocabulary.find(w=>w.id===$('#writingWord').value);if(w)speak(w.hanzi)};
const research=[{name:'HelloChinese',label:'통합 학습 · 반복 복습',url:'https://www.hellochinese.cc/',points:['짧은 게임형 수업','읽기·쓰기·말하기·어휘·문법','음성 인식·필기·간격 반복 복습'],note:'이 앱에는 단어 카드·짧은 퀴즈·쓰기 연습을 적용했습니다.'},{name:'ChineseSkill',label:'단계별 코스 · 학습 동기',url:'https://www.chineseskill.com/',points:['입문부터 이어지는 단계별 과정','15분 단위의 짧은 수업','원어민 음성·활동·성취 요소'],note:'이 앱에는 레벨별 코스·진도와 일일 학습 목표를 적용했습니다.'},{name:'SuperChinese',label:'상황 중심 · 스마트 복습',url:'https://superchinese.com/features.html',points:['실생활 주제별 학습','어휘·문법·회화의 구조적 학습','말하기 훈련·게임화·복습 시스템'],note:'이 앱에는 일상·카페·여행 등의 주제와 자가 평가 복습을 적용했습니다.'}];$('#researchGrid').innerHTML=research.map((r,i)=>`<article class="panel research-card"><span class="eyebrow">0${i+1} / ${r.label}</span><h2>${r.name}</h2><ul>${r.points.map(p=>`<li>${p}</li>`).join('')}</ul><p>${r.note}</p><a href="${r.url}" target="_blank" rel="noopener">공식 서비스 소개 ↗</a></article>`).join('');
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!data)return;if(b.hasAttribute('data-close'))return close();if(b.dataset.lesson)return startLesson(b.dataset.lesson);if(b.dataset.editWord)return wordEditor(b.dataset.editWord);if(b.dataset.editLesson)return lessonEditor(b.dataset.editLesson);if(b.dataset.deleteWord){const w=data.vocabulary.find(w=>w.id===b.dataset.deleteWord);return confirmAction('단어를 삭제할까요?',`${w.hanzi} 단어와 관련 수업의 단어 연결이 삭제됩니다.`,()=>{data.vocabulary=data.vocabulary.filter(x=>x.id!==w.id);data.lessons.forEach(l=>l.wordIds=l.wordIds.filter(id=>id!==w.id));persist();toast('단어를 삭제했습니다.')})}if(b.dataset.deleteLesson){const l=data.lessons.find(l=>l.id===b.dataset.deleteLesson);return confirmAction('수업을 삭제할까요?',`${l.title} 수업을 삭제합니다. 단어장과 기존 학습 결과 기록은 유지됩니다.`,()=>{data.lessons=data.lessons.filter(x=>x.id!==l.id);persist();toast('수업을 삭제했습니다.')})}if(b.dataset.exampleSpeak){const w=data.vocabulary.find(w=>w.id===b.dataset.exampleSpeak);return w&&speak(w.example)}if(b.dataset.speak){const w=data.vocabulary.find(w=>w.id===b.dataset.speak);return w&&speak(w.hanzi)}if(b.dataset.rating){const wordId=reviewQueue.shift();data.vocabulary=data.vocabulary.map(w=>w.id===wordId?schedule(w,b.dataset.rating):w);revealed=false;persist();return}switch(b.dataset.action){case'addWord':wordEditor();break;case'addLesson':lessonEditor();break;case'activity':activityEditor();break;case'continue':{const l=recommendation();if(l)startLesson(l.id);else{location.hash='lessons';lessonEditor()}break}case'data':dataDialog();break}});
$('#settings').onclick=settings;$('#dataMenu').onclick=dataDialog;$('#wordSearch').oninput=renderWords;$('#wordCategory').onchange=renderWords;$('#lessonLevel').onchange=renderLessons;window.addEventListener('hashchange',route);window.addEventListener('storage',e=>{if(e.key===KEY)toast('다른 탭에서 데이터가 변경됐습니다. 현재 탭을 새로고침한 뒤 작업하세요.')});
try{const response=await fetch('./data.json?v=20261029');if(!response.ok)throw new Error('초기 JSON을 읽을 수 없습니다.');seed=validate(await response.json());try{const stored=localStorage.getItem(KEY);data=stored?enrichExisting(validate(JSON.parse(stored)),seed):structuredClone(seed)}catch{data=structuredClone(seed);toast('저장 데이터 형식을 읽지 못해 초기 예시를 표시합니다. 기존 저장본은 자동 덮어쓰지 않습니다.')}route()}catch(err){$('#view-dashboard').innerHTML=`<div class="panel"><h1>학습 데이터를 열지 못했습니다.</h1><p>${esc(err.message)}</p><p>index.html을 파일로 직접 여는 대신 정적 웹서버 또는 GitHub Pages에서 실행하세요.</p></div>`}

